--- command ---
package main

import (
	"encoding/csv"
	"fmt"
	"os"
	"sort"
	"strconv"

	"contractor/internal/electrical"
)

func main() {
	file, err := os.Open("data/readings.csv")
	if err != nil {
		panic(err)
	}
	defer file.Close()

	records, err := csv.NewReader(file).ReadAll()
	if err != nil {
		panic(err)
	}
	rows := make([]electrical.Reading, 0, len(records)-1)
	for _, record := range records[1:] {
		value, err := strconv.ParseFloat(record[3], 64)
		if err != nil {
			panic(err)
		}
		rows = append(rows, electrical.Reading{Site: record[0], Circuit: record[1], Week: record[2], Megohms: value})
	}

	summaries := electrical.SummarizeWeek(rows, "2025-W18")
	sites := make([]string, 0, len(summaries))
	for site := range summaries {
		sites = append(sites, site)
	}
	sort.Strings(sites)
	for _, site := range sites {
		summary := summaries[site]
		fmt.Printf("%s: readings=%v normal=%d out_of_range=%d\n", site, summary.Readings, summary.Normal, summary.OutOfRange)
	}
}

