LOWER_HCG_IU_L = 2.0
UPPER_HCG_IU_L = 10.0


def mark_out_of_range(records):
    marked = []
    for record in records:
        value = float(record["hcg_iu_l"])
        marked.append(
            {
                **record,
                "out_of_range": value < LOWER_HCG_IU_L or value > UPPER_HCG_IU_L,
            }
        )
    return marked

