package main

import (
	"fmt"
	"os"

	"garage/internal/emissions"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: import-co <path>")
		os.Exit(2)
	}
	file, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer file.Close()
	rows, err := emissions.Import(file)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	for _, row := range rows {
		fmt.Printf("%s %s %.2f\n", row.VehicleID, row.ObservedAt, row.COPercent)
	}
}
