import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"example.com/volt/internal/electrical"
)

func main() {
	f, err := os.Open("data/circuits.csv")
	if err != nil {
		panic(err)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Scan()
	for scanner.Scan() {
		fields := strings.Split(scanner.Text(), ",")
		value, _ := strconv.ParseFloat(fields[1], 64)
		c := electrical.Circuit{ID: fields[0], ResistanceMOhm: value}
		fmt.Printf("%s %t\n", c.ID, electrical.FlagOutOfRange(c))
	}
}

