import (
	"encoding/csv"
	"fmt"
	"os"
	"strconv"

	"fleetdesk/internal/emissions"
)

func main() {
	f, err := os.Open("samples/co_readings.csv")
	if err != nil {
		panic(err)
	}
	defer f.Close()

	rows, err := csv.NewReader(f).ReadAll()
	if err != nil {
		panic(err)
	}
	for _, row := range rows[1:] {
		co, err := strconv.ParseFloat(row[2], 64)
		if err != nil {
			panic(err)
		}
		r := emissions.Reading{VehicleID: row[0], COPercent: co}
		fmt.Printf("%s %t\n", r.VehicleID, emissions.NeedsAttention(r))
	}
}

